            'proyecto_codigo_interno',
            'proyecto_presupuesto',
            'proyecto_entregables',
            'proyecto_soportes',
        ];
        return array_map(static function (array $field) use ($evidenceFields, $fieldApplyMap, $commonIntangibleFields): array {
            if (!in_array($field['name'], $commonIntangibleFields, true) && !isset($field['applies_to'])) {
                $field['applies_to'] = $fieldApplyMap[$field['name']] ?? [];
            }
            if (in_array($field['name'], $evidenceFields, true)) {
                $field['evidence'] = true;
            }
            return $field;
        }, $fields);
    }

